  const order = await (await post({ items: [{ sku: 'B', qty: 2 }] })).json()
  assert.equal(order.total, 108)
})

test('POST /orders gives no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 10 }] })).json()
  assert.equal(order.total, 100)
})

test('POST /orders floors the total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — total is floored to whole euros (10.5 -> 10), dropping cents
  const order = await (await post({ items: [{ sku: 'C', qty: 1 }] })).json()
  assert.equal(order.total, 10)
})

test('POST /orders floors after discount', async () => {
  // 11 x 10.5 = 115.5 -> 103.95 -> 103
  const order = await (await post({ items: [{ sku: 'C', qty: 11 }] })).json()
  assert.equal(order.total, 103)
})

test('POST /orders with missing qty yields a null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no item validation: qty undefined gives NaN, serialised as null, order still 201
  const res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

